import logging
from math import pi, sin
from taf.hw.mcs.mcs import MCS
from taf.hw.mcs.executor.socket_connection import SocketConnection
from taf.hw.mcs.devices.topyoung.command import Command


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Topyoung(MCS):

    _vendor = "TOPYOUNG"
    _model = None
    _version = None
    _CHANNEL_FORMAT = r"A{input_channel}B{output_channel}"

    _DEFAULT_ROW_PORT_NUMBER = None
    _DEFAULT_COL_PORT_NUMBER = None

    def __init__(self, server_ip=None, server_port=1888, device_ip=None, db_path=None,
                 row_num=None, column_num=None, **kwargs):
        super(Topyoung, self).__init__(**kwargs)
        self._server_ip = server_ip
        self._server_port = server_port
        self._device_ip = device_ip
        self._db_path = db_path
        self._row_num = row_num or self._DEFAULT_ROW_PORT_NUMBER
        self._column_num = column_num or self._DEFAULT_COL_PORT_NUMBER
        self._socket_client = None
        self._command = None
        self._phase_caculator = self._create_phase_calulator()

    def connect(self):
        self._connect_socket()
        self._create_command()
        self._connect_command()

    def disconnect(self):
        self._disconnect_command()
        self._disconnect_socket()

    def _connect_socket(self):
        self._socket_client = SocketConnection(self._server_ip, self._server_port)
        self._socket_client.connect_socket()

    def _create_command(self):
        self._command = Command(self._socket_client, self._device_ip, self._db_path)

    def _connect_command(self):
        self._command.connect()

    def _disconnect_command(self):
        self._command.disconnect()

    def _disconnect_socket(self):
        self._socket_client.close_socket()

    def set_frequency(self, frequency, timeout=None):
        return self._command.set_frequency(frequency, timeout=timeout)

    def set_phases_according_to_angles(self, vertical_angle, horizontal_angle,
                                       vertical_distance, horizontal_distance,
                                       output_group_id, input_group_id):
        phase = self._phase_caculator.get_phase(vertical_angle, horizontal_angle,
                                                vertical_distance, horizontal_distance,
                                                input_group_id)

        input_channels = [input_group_id * 2 - 1, input_group_id * 2]
        channels = [self._get_channel(input_channel, output_group_id) for input_channel in input_channels]
        phases = [phase] * len(channels)
        return self._command.set_phases(channels, phases)

    def _create_phase_calulator(self):
        return PhaseCaculator()

    def set_phase(self, phase, input_channel, output_channel):
        channel = self._get_channel(input_channel, output_channel)
        self._command.set_phase(channel, phase)

    def get_phase(self, input_channel, output_channel):
        channel = self._get_channel(input_channel, output_channel)
        return self._command.get_phase(channel)

    def set_phases(self, phase, begin_input_channel=1, end_input_channel=64, output_channel=1):
        channels = [self._get_channel(input_channel, output_channel)
                    for input_channel in range(begin_input_channel, end_input_channel + 1)]
        phases = [phase] * len(channels)
        return self._command.set_phases(channels, phases)

    def set_attenuation(self, attenuation, input_channel, output_channel):
        channel = self._get_channel(input_channel, output_channel)
        self._command.set_attenuation(channel, attenuation)

    def get_attenuation(self, input_channel, output_channel):
        channel = self._get_channel(input_channel, output_channel)
        return self._command.get_attenuation(channel)

    def set_odd_attenuations(self, attenuation, begin_input_channel, end_input_channel, output_channel):
        channels = [self._get_channel(input_channel, output_channel)
                    for input_channel in range(begin_input_channel, end_input_channel + 1) if input_channel % 2]
        attenuations = [attenuation] * len(channels)
        self._command.set_attenuations(channels, attenuations)

    def set_even_attenuations(self, attenuation, begin_input_channel, end_input_channel, output_channel):
        channels = [self._get_channel(input_channel, output_channel)
                    for input_channel in range(begin_input_channel, end_input_channel + 1) if input_channel % 2 == 0]
        attenuations = [attenuation] * len(channels)
        self._command.set_attenuations(channels, attenuations)

    def _get_channel(self, input_channel, output_channel):
        if input_channel > self._row_num or output_channel > self._column_num:
            raise Exception("{} or {} exceed max number".format(input_channel, output_channel))
        return self._CHANNEL_FORMAT.format(input_channel=input_channel, output_channel=output_channel)

    def set_matrix_number(self, number):
        return self._command.set_matrix_number(number)

    def read_matrix_number(self):
        return self._command.read_matrix_number()

    def set_position(self, matrix_positions):
        return self._command.set_position(matrix_positions)

    def read_position(self, matrix_id):
        return self._command.read_position(matrix_id)

    def set_aedis(self, matrix_id,
                  horizontal_d_value, vertical_d_value,
                  ul_horizontal_d_value, ul_vertical_d_value):
        return self._command.set_aedis(
            matrix_id, horizontal_d_value, vertical_d_value, ul_horizontal_d_value, ul_vertical_d_value)

    def read_aedis(self):
        return self._command.read_aedis()

    def set_beam(self, port, matrix_id, horizontal_beam_angle, vertical_beam_angle,
                 even_attenuation_enable, event_attenuation_value,
                 odd_attenuation_enable, odd_attenuation_value):
        return self._command.set_beam(port, matrix_id, horizontal_beam_angle, vertical_beam_angle,
                                      even_attenuation_enable, event_attenuation_value,
                                      odd_attenuation_enable, odd_attenuation_value)


class PhaseCaculator(object):

    def get_phase(self, vertical_angle, horizontal_angle, vertical_distance, horizontal_distance, input_group_id):
        horizontal_id, vertical_id = self._get_horizontal_and_vertical_id(input_group_id)
        horizontal_phase = self._calc_phase_formula(horizontal_id, horizontal_distance, horizontal_angle)
        vertical_phase = self._calc_phase_formula(vertical_id, vertical_distance, vertical_angle)
        logger.debug("horizontal_phase: {} vertical_phase: {}".format(horizontal_phase, vertical_phase))
        return self._get_setting_phase_value(horizontal_phase, vertical_phase)

    @staticmethod
    def _get_setting_phase_value(horizontal_phase, vertical_phase):
        return (horizontal_phase + vertical_phase + 360) % 360

    @staticmethod
    def _get_horizontal_and_vertical_id(input_group_id):
        horizontal_id, vertical_id = (input_group_id - 1) % 8 + 1, int((input_group_id - 1) / 8) + 1
        return horizontal_id, vertical_id

    @staticmethod
    def _calc_phase_formula(direction_id, distance, angle):
        return (direction_id - 1) * 360 * distance * sin(float(angle * pi / 180))


class Phase12BitsCaculator(PhaseCaculator):

    @staticmethod
    def _get_setting_phase_value(horizontal_phase, vertical_phase):
        return int((horizontal_phase + vertical_phase + 3 * 360) % 360 * 4096 / 360)
